5	use App\Listeners\RecordScheduledTaskHeartbeat;
6	use App\Models\Core\Professional\ProfessionalIntegration;
7	use App\Policies\IntegrationPolicy;
8	use Illuminate\Cache\RateLimiting\Limit;
9	use Illuminate\Console\Events\ScheduledTaskStarting;
10	use Illuminate\Database\Eloquent\Model;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Facades\Event;
13	use Illuminate\Support\Facades\Gate;
14	use Illuminate\Support\Facades\RateLimiter;
15	use Illuminate\Support\ServiceProvider;
16	
17	// V2: Bootstraps application-wide rate limiters for public, authenticated, webhook, staff, and internal API routes.
18	class AppServiceProvider extends ServiceProvider
19	{
20	    /**
21	     * Register any application services.
22	     */
23	    public function register(): void
24	    {
25	        $this->app->singleton(\App\Services\Shopify\Client\ShopifyAdminClient::class);
26	        $this->app->singleton(\App\Services\Shopify\Client\ShopifyBudgetTracker::class);
27	        $this->app->singleton(\App\Services\Shopify\Client\ShopifyCostTracker::class);
28	        $this->app->singleton(\App\Services\Shopify\Client\ShopifyMetrics::class);
29	        $this->app->singleton(\App\Services\Shopify\Client\ShopifyBulkOperationLock::class);
30	    }
31	
32	    /**
33	     * Bootstrap any application services.
34	     */
35	    public function boot(): void
36	    {
37	        Gate::policy(ProfessionalIntegration::class, IntegrationPolicy::class);
38	
39	        $this->configureRateLimiting();
40	
41	        // Scheduler heartbeat — feeds GET /api/health/scheduler so a stopped cron
42	        // runner becomes visible. See RecordScheduledTaskHeartbeat for rationale.
43	        Event::listen(ScheduledTaskStarting::class, RecordScheduledTaskHeartbeat::class);
44	
45	        // Strict-mode N+1 trap: throw on unloaded relation access outside production
46	        // so tests/local catch lazy loading instead of leaking slow queries to prod.
47	        Model::preventLazyLoading(! app()->isProduction());
48	    }
49	
50	    /**
51	     * Configure the rate limiters for the application.
52	     */
53	    protected function configureRateLimiting(): void
54	    {
55	        $throttleEnabled = (bool) config('sidest.throttle.enabled', true);
56	
57	        // Public site endpoints (viewing sites, pages)
58	        RateLimiter::for('public-site', function (Request $request) use ($throttleEnabled) {
59	            if (! $throttleEnabled) {
60	                return Limit::none();
61	            }
62	
63	            return Limit::perMinute(60)
64	                ->by($request->ip())
65	                ->response(function () {
66	                    return response()->json([
67	                        'message' => 'Too many requests.  Please try again later.',
68	                    ], 429);
69	                });
70	        });
71	
72	        // Booking checkout — tighter limit because checkout hits Stripe/Square synchronously
73	        RateLimiter::for('booking-checkout', function (Request $request) use ($throttleEnabled) {
74	            if (! $throttleEnabled) {
75	                return Limit::none();
76	            }
77	
78	            return Limit::perMinute(10)
79	                ->by($request->ip())
80	                ->response(function () {
81	                    return response()->json([
82	                        'message' => 'Too many booking attempts. Please try again shortly.',
83	                    ], 429);
84	                });
85	        });
86	
87	        // Analytics endpoints (pageviews, clicks)
88	        RateLimiter::for('analytics', function (Request $request) use ($throttleEnabled) {
89	            if (! $throttleEnabled) {
90	                return Limit::none();
91	            }
92	
93	            return Limit::perMinute(120)
94	                ->by($request->ip());
95	        });
96	
97	        // Customer lead submissions (form submissions)
98	        RateLimiter::for('leads', function (Request $request) use ($throttleEnabled) {
99	            if (! $throttleEnabled) {
100	                return [Limit::none()];
101	            }
102	
103	            $subdomain = $request->route('subdomain') ?? 'unknown';
104	
105	            return [
106	                // Per IP:  3 submissions per minute
107	                Limit::perMinute(3)
108	                    ->by($request->ip())
109	                    ->response(function () {
110	                        return response()->json([
111	                            'message' => 'Too many submissions. Please wait before trying again.',
112	                        ], 429);
113	                    }),
114	
115	                // Per subdomain: 100 submissions per minute (prevent abuse)
116	                Limit::perMinute(100)
117	                    ->by($subdomain)
118	                    ->response(function () {
119	                        return response()->json([
120	                            'message' => 'This site is receiving too many submissions. Please try again later.',
121	                        ], 429);
122	                    }),
123	            ];
124	        });
125	
126	        // Public waitlist submissions
127	        RateLimiter::for('waitlist', function (Request $request) use ($throttleEnabled) {
128	            if (! $throttleEnabled) {
129	                return [Limit::none()];
130	            }
131	
132	            $email = strtolower(trim((string) $request->input('email', '')));
133	            $emailKey = $email !== '' ? hash('sha256', $email) : 'unknown';
134	
135	            return [
136	                Limit::perMinute(5)
137	                    ->by('waitlist:ip:'.$request->ip())
138	                    ->response(function () {
139	                        return response()->json([
140	                            'message' => 'Too many waitlist submissions. Please try again shortly.',
141	                        ], 429);
142	                    }),
143	
144	                Limit::perHour(12)
145	                    ->by('waitlist:email:'.$emailKey)
146	                    ->response(function () {
147	                        return response()->json([
148	                            'message' => 'This email has been submitted recently. Please try again later.',
149	                        ], 429);
150	                    }),
151	            ];
152	        });
153	
154	        // Shopify webhook endpoints (keyed by shop domain, fallback to IP)
155	        RateLimiter::for('shopify-webhooks', function (Request $request) use ($throttleEnabled) {
156	            if (! $throttleEnabled) {
157	                return Limit::none();
158	            }
159	
160	            $key = strtolower(trim((string) $request->header('x-shopify-shop-domain', '')));
161	            if ($key === '') {
162	                $key = $request->ip();
163	            }
164	
165	            return Limit::perMinute(120)
166	                ->by($key)
167	                ->response(function () {
168	                    return response()->json(['message' => 'Too many webhook requests.'], 429);
169	                });
170	        });
171	
172	        // Affiliate selection write operations (create, delete, reorder)
173	        RateLimiter::for('affiliate-writes', function (Request $request) use ($throttleEnabled) {
174	            if (! $throttleEnabled) {
175	                return Limit::none();
176	            }
177	
178	            return Limit::perMinute(60)
179	                ->by($request->attributes->get('supabase_uid') ?? $request->ip())
180	                ->response(function () {
181	                    return response()->json([
182	                        'message' => 'Too many selection changes. Please try again later.',
183	                    ], 429);
184	                });
185	        });
186	
187	        // Brand catalog write operations (metafield updates, collection management)
188	        RateLimiter::for('brand-catalog-writes', function (Request $request) use ($throttleEnabled) {
189	            if (! $throttleEnabled) {
190	                return Limit::none();
191	            }
192	
193	            return Limit::perMinute(30)
194	                ->by($request->attributes->get('supabase_uid') ?? $request->ip())
195	                ->response(function () {
196	                    return response()->json([
197	                        'message' => 'Too many catalog changes. Please try again later.',
198	                    ], 429);
199	                });
200	        });
201	
202	        // Authenticated professional routes
203	        RateLimiter::for('authenticated', function (Request $request) use ($throttleEnabled) {
204	            if (! $throttleEnabled) {
205	                return Limit::none();
206	            }
207	
208	            return Limit::perMinute(300)
209	                ->by($request->attributes->get('supabase_uid') ?? $request->ip())
210	                ->response(function () {
211	                    return response()->json([
212	                        'message' => 'Too many requests. Please try again later.',
213	                    ], 429);
214	                });
215	        });
216	
217	        // Staff panel routes
218	        RateLimiter::for('staff', function (Request $request) use ($throttleEnabled) {
219	            if (! $throttleEnabled) {
220	                return Limit::none();
221	            }
222	
223	            return Limit::perMinute(300)
224	                ->by($request->attributes->get('supabase_uid') ?? $request->ip())
225	                ->response(function () {
226	                    return response()->json([
227	                        'message' => 'Too many requests. Please try again later.',
228	                    ], 429);
229	                });
230	        });
231	
232	        // Webhook endpoints (Square, Fresha, Stripe Connect)
233	        RateLimiter::for('webhooks', function (Request $request) use ($throttleEnabled) {
234	            if (! $throttleEnabled) {
235	                return Limit::none();
236	            }
237	
238	            return Limit::perMinute(200)
239	                ->by($request->ip())
240	                ->response(function () {
241	                    return response()->json([
242	                        'message' => 'Too many webhook requests.',
243	                    ], 429);
244	                });
245	        });
246	
247	        // Account bootstrap (creation)
248	        RateLimiter::for('bootstrap', function (Request $request) use ($throttleEnabled) {
249	            if (! $throttleEnabled) {
250	                return Limit::none();
251	            }
252	
253	            return Limit::perMinute(5)
254	                ->by($request->attributes->get('supabase_uid') ?? $request->ip())
255	                ->response(function () {
256	                    return response()->json([
257	                        'message' => 'Too many account creation attempts. Please try again later.',
258	                    ], 429);
259	                });
260	        });
261	
262	        // Internal Hydrogen endpoints (server-to-server)
263	        RateLimiter::for('hydrogen-internal', function (Request $request) use ($throttleEnabled) {
264	            if (! $throttleEnabled) {
265	                return Limit::none();
266	            }
267	
268	            return Limit::perMinute(120)
269	                ->by($request->ip())
270	                ->response(function () {
271	                    return response()->json([
272	                        'message' => 'Too many requests.',
273	                    ], 429);
274	                });
275	        });
276	
277	        // Public plans listing
278	        RateLimiter::for('plans', function (Request $request) use ($throttleEnabled) {
279	            if (! $throttleEnabled) {
280	                return Limit::none();
281	            }
282	
283	            return Limit::perMinute(30)
284	                ->by($request->ip())
285	                ->response(function () {
286	                    return response()->json([
287	                        'message' => 'Too many requests. Please try again later.',
288	                    ], 429);
289	                });
290	        });
291	    }
