90	                return Limit::none();
91	            }
92	
93	            return Limit::perMinute(120)
94	                ->by($request->ip());
95	        });
96	
97	        // Customer lead submissions (form submissions)
98	        RateLimiter::for('leads', function (Request $request) use ($throttleEnabled) {
