61	        // Handle API exceptions with JSON responses
62	        $exceptions->render(function (Throwable $e, Request $request) {
63	            // Only handle API routes
64	            if (! $request->is('api/*')) {
65	                return null;
66	            }
67	
68	            // Validation errors (422)
69	            if ($e instanceof ValidationException) {
70	                return response()->json([
71	                    'message' => 'Validation failed',
72	                    'errors' => $e->errors(),
73	                ], 422);
74	            }
75	
76	            // Model not found (404)
77	            if ($e instanceof ModelNotFoundException) {
78	                return response()->json([
79	                    'message' => 'Resource not found',
80	                ], 404);
81	            }
82	
83	            // Not found (404)
84	            if ($e instanceof NotFoundHttpException) {
85	                return response()->json([
86	                    'message' => 'Endpoint not found',
87	                ], 404);
88	            }
89	
90	            // Forbidden (403)
91	            if ($e instanceof AccessDeniedHttpException) {
92	                \Illuminate\Support\Facades\Log::warning('Access denied', [
93	                    'path' => $request->path(),
94	                    'message' => $e->getMessage(),
95	                ]);
96	
97	                return response()->json([
98	                    'message' => $e->getMessage() ?: 'Access denied',
99	                ], 403);
100	            }
101	
102	            // Preserve explicit response exceptions (e.g. throttle 429)
103	            if ($e instanceof HttpResponseException) {
104	                return $e->getResponse();
105	            }
106	
107	            // Generic error handling
108	            $statusCode = 500;
109	            if ($e instanceof \Symfony\Component\HttpKernel\Exception\HttpException) {
110	                $statusCode = $e->getStatusCode();
111	            }
112	
113	            // Log full exception for debugging even in production
114	            if ($statusCode >= 500) {
115	                \Illuminate\Support\Facades\Log::error('API Error', [
116	                    'exception' => $e,
117	                    'status' => $statusCode,
118	                ]);
119	            }
120	
121	            // Don't expose internal errors in production
122	            $message = config('app.debug')
123	                ? $e->getMessage()
124	                : 'An error occurred';
125	
126	            return response()->json([
127	                'message' => $message,
128	            ], $statusCode);
129	        });
