3	namespace App\Http\Middleware\Auth;
4	
5	use App\Services\Cache\CacheLockService;
6	use Closure;
7	use Firebase\JWT\JWK;
8	use Firebase\JWT\JWT;
9	use Illuminate\Http\Request;
10	use Illuminate\Support\Facades\Http;
11	use Illuminate\Support\Facades\Log;
12	use Symfony\Component\HttpFoundation\Response;
13	
14	// V2: JWT authentication via Supabase JWKS (asymmetric). Falls back to Auth Server query. All authenticated routes require this.
15	class VerifySupabaseJwt
16	{
17	    public function __construct(private CacheLockService $cacheLock) {}
18	
19	    public function handle(Request $request, Closure $next): Response
20	    {
21	        $token = $this->getBearerToken($request);
22	        if (! $token) {
23	            return response()->json(['message' => 'Missing Bearer token'], 401);
24	        }
25	
26	        // 1) Try verify via JWKS (asymmetric signing)
27	        try {
28	            $claims = $this->verifyWithJwks($token);
29	
30	            // Validate issuer/audience (extra safety)
31	            if (! $this->claimsMatchConfig($claims)) {
32	                return response()->json(['message' => 'Invalid token claims'], 401);
33	            }
34	
35	            $uid = $claims['sub'] ?? null;
36	            if (! $uid) {
37	                return response()->json(['message' => 'Token missing sub'], 401);
38	            }
39	
40	            $this->setSupabaseContext($request, $uid, $claims);
41	
42	            return $next($request);
43	        } catch (\Throwable $e) {
44	            // Log every JWKS failure before falling back — repeated infra-level failures
45	            // (e.g. network blocking JWKS fetches) are security-relevant and must be visible.
46	            Log::warning('JWT JWKS verification failed, falling back to auth server', [
47	                'reason' => $e->getMessage(),
48	                'ip' => $request->ip(),
49	            ]);
50	
51	            // 2) Fallback for legacy/shared-secret setups:
52	            // Supabase recommends verifying by calling Auth server /user. :contentReference[oaicite:2]{index=2}
53	            try {
54	                $uid = $this->verifyWithAuthServer($token);
55	                if (! $uid) {
56	                    return response()->json(['message' => 'Invalid token'], 401);
57	                }
58	
59	                $this->setSupabaseContext($request, $uid);
60	
61	                return $next($request);
62	            } catch (\Throwable $e2) {
63	                Log::warning('JWT verification failed', [
64	                    'reason' => $e2->getMessage(),
65	                    'ip' => $request->ip(),
66	                ]);
67	
68	                return response()->json(['message' => 'Invalid token'], 401);
69	            }
70	        }
71	    }
72	
73	    private function getBearerToken(Request $request): ?string
74	    {
75	        $auth = (string) $request->header('Authorization', '');
76	        if (! str_starts_with($auth, 'Bearer ')) {
77	            return null;
78	        }
79	
80	        return trim(substr($auth, 7));
81	    }
82	
83	    private function setSupabaseContext(Request $request, string $uid, ?array $claims = null): void
84	    {
85	        $request->attributes->set('supabase_uid', $uid);
86	
87	        if ($claims !== null) {
88	            $request->attributes->set('supabase_claims', $claims);
89	        }
90	
91	        // Nightwatch falls back to hidden context when no Laravel auth guard is resolved.
92	        if (class_exists(\Laravel\Nightwatch\Compatibility::class)) {
93	            \Laravel\Nightwatch\Compatibility::addUserIdToContext($uid);
94	        }
95	    }
96	
97	    private function verifyWithJwks(string $jwt): array
98	    {
99	        $parts = explode('.', $jwt);
100	        if (count($parts) !== 3) {
101	            throw new \RuntimeException('Invalid JWT format');
102	        }
103	
104	        $header = json_decode($this->b64urlDecode($parts[0]), true) ?: [];
105	
106	        // Reject non-RS256 tokens before key lookup to prevent algorithm confusion attacks
107	        // (e.g. HS256 signed with the public key as the HMAC secret).
108	        $alg = $header['alg'] ?? null;
109	        if ($alg !== 'RS256') {
110	            throw new \RuntimeException('JWT alg must be RS256, got: '.($alg ?? 'none'));
111	        }
112	
113	        $kid = $header['kid'] ?? null;
114	        if (! $kid) {
115	            throw new \RuntimeException('JWT header missing kid');
116	        }
117	
118	        $jwksUrl = config('supabase.jwks_url');
119	        if (! $jwksUrl) {
120	            throw new \RuntimeException('Missing SUPABASE_JWKS_URL');
121	        }
122	
123	        $jwks = $this->cacheLock->rememberLocked('supabase:jwks', config('supabase.jwks_cache_seconds', 300), function () use ($jwksUrl) {
124	            $res = Http::timeout(5)->get($jwksUrl);
125	            if (! $res->ok()) {
126	                throw new \RuntimeException('Failed to fetch JWKS');
127	            }
128	
129	            $payload = $res->json();
130	            if (! is_array($payload)) {
131	                // Empty/invalid JSON body — never cache this. Throwing keeps the lock-release
132	                // path clean and lets the caller's error logging surface the infra problem.
133	                throw new \RuntimeException('JWKS response did not parse to an array');
134	            }
135	
136	            return $payload;
137	        });
138	
139	        // If your project isn't using asymmetric keys, JWKS may be empty. :contentReference[oaicite:3]{index=3}
140	        if (empty($jwks['keys'])) {
141	            throw new \RuntimeException('JWKS empty');
142	        }
143	
144	        $keys = JWK::parseKeySet($jwks);
145	        $key = $keys[$kid] ?? null;
146	        if (! $key) {
147	            throw new \RuntimeException('No matching JWKS key for kid');
148	        }
149	
150	        // Decode + verify signature + exp/nbf automatically
151	        JWT::$leeway = 60; // clock skew tolerance
152	        $decoded = JWT::decode($jwt, $key);
153	
154	        return json_decode(json_encode($decoded), true) ?: [];
155	    }
156	
157	    private function verifyWithAuthServer(string $jwt): ?string
158	    {
159	        $baseUrl = rtrim((string) config('supabase.url'), '/');
160	        $anonKey = (string) config('supabase.anon_key');
161	
162	        if (! $baseUrl || ! $anonKey) {
163	            throw new \RuntimeException('Missing SUPABASE_URL or SUPABASE_ANON_KEY');
164	        }
165	
166	        $res = Http::timeout(5)
167	            ->withHeaders([
168	                'apikey' => $anonKey,
169	                'Authorization' => 'Bearer '.$jwt,
170	            ])
171	            ->get($baseUrl.'/auth/v1/user');
172	
173	        if (! $res->ok()) {
174	            return null;
175	        }
176	
177	        $user = $res->json();
178	
179	        return $user['id'] ?? null; // Supabase user id
180	    }
181	
182	    private function claimsMatchConfig(array $claims): bool
183	    {
184	        $issExpected = (string) config('supabase.jwt_issuer');
185	        $audExpected = (string) config('supabase.jwt_audience');
186	
187	        if ($issExpected && (($claims['iss'] ?? null) !== $issExpected)) {
188	            return false;
189	        }
190	
191	        $aud = $claims['aud'] ?? null;
192	        if ($audExpected) {
193	            if (is_array($aud)) {
194	                if (! in_array($audExpected, $aud, true)) {
195	                    return false;
196	                }
197	            } else {
198	                if ($aud !== $audExpected) {
199	                    return false;
200	                }
201	            }
202	        }
203	
204	        return true;
205	    }
206	
207	    private function b64urlDecode(string $data): string
208	    {
209	        $data = strtr($data, '-_', '+/');
210	        $pad = strlen($data) % 4;
211	        if ($pad) {
212	            $data .= str_repeat('=', 4 - $pad);
213	        }
214	
215	        return base64_decode($data) ?: '';
216	    }
217	}
