15	        private ProfessionalCacheService $professionalCache
16	    ) {}
17	
18	    public function handle(Request $request, Closure $next): Response
19	    {
20	
21	        Log::debug('LoadCurrentProfessional start');
22	
23	        $uid = $request->attributes->get('supabase_uid');
24	        if (! $uid) {
25	            Log::debug('LoadCurrentProfessional missing uid');
26	
27	            return response()->json(['message' => 'Missing uid'], 401);
28	        }
29	
30	        Log::debug('LoadCurrentProfessional before cache getByAuthId', ['uid' => $uid]);
31	
32	        // Use cache service instead of a direct query
33	        $professional = $this->professionalCache->getByAuthId($uid);
34	
35	        Log::debug('LoadCurrentProfessional after cache getByAuthId', [
36	            'uid' => $uid,
37	            'found' => (bool) $professional,
38	        ]);
39	
40	        if (! $professional) {
41	            // Important: /api/bootstrap should create this row
42	            Log::debug('LoadCurrentProfessional no professional for uid', ['uid' => $uid]);
43	
44	            return response()->json([
45	                'message' => 'professional profile missing. Call /api/bootstrap first.',
46	            ], 403);
47	        }
48	
49	        $status = $professional->status ?? 'active';
50	        if (! in_array($status, ['active', 'pending_deletion'], true)) {
51	            Log::debug('LoadCurrentProfessional blocked account', [
52	                'uid' => $uid,
53	                'status' => $status,
54	            ]);
