57	                'message' => 'Your account is not active. Contact support.',
58	            ], 403);
59	        }
60	
61	        $request->attributes->set('professional', $professional);
62	
63	        Log::debug('LoadCurrentProfessional before next middleware');
64	
65	        return $next($request);
66	    }
